// Fork watcher, run by .github/workflows/fork-watch.yml through actions/github-script.
// Lists recent commits touching vaft / userscript files in the repos of
// .github/watched-forks.json and in their recently pushed forks, then keeps ONE open
// issue (label "upstream-watch") up to date. Stateless: a fixed look-back window
// (windowDays, 8 for a weekly run = 1 day overlap) plus de-duplication against the
// commit links already in the open issue. Read-only on other repos; writes only
// the issue (and its label) in the repo running the workflow.
'use strict';
const fs = require('fs');
const path = require('path');

const DAY_MS = 86400000;
const MARKER = '<!-- fork-watch: generated by .github/workflows/fork-watch.yml, edits are overwritten -->';

function httpStatus(err) {
    return err?.status ?? err?.response?.status;
}

function isRateLimit(err) {
    const s = httpStatus(err);
    if (s === 429) return true;
    if (s !== 403) return false;
    return /rate limit/i.test(err?.message || '') || err?.response?.headers?.['x-ratelimit-remaining'] === '0';
}

// One-line, table-safe text. Commit messages come from other repos: break @mentions
// and #123 / GH-123 refs so the issue never pings people or cross-links our issues.
function cell(text, max = 100) {
    const oneLine = String(text ?? '').split('\n')[0].trim();
    const cut = oneLine.length > max ? `${oneLine.slice(0, max - 1)}…` : oneLine;
    return cut
        .replace(/\|/g, '\\|')
        .replace(/</g, '&lt;')
        .replace(/@(?=\w)/g, '@\u200b')
        .replace(/(#|GH-)(?=\d)/gi, '$1\u200b');
}

function renderReport({ findings, checked, notes, since, now, windowDays, truncated }) {
    const lines = [
        MARKER,
        `Commits touching vaft / userscript files in the last ${windowDays} days (since ${since.toISOString().slice(0, 10)}), checked ${now.toISOString().slice(0, 16).replace('T', ' ')} UTC.`,
        '',
    ];
    if (findings.length) {
        lines.push('| repo | commit | date (UTC) | author | message | path |', '|---|---|---|---|---|---|');
        for (const f of findings) {
            lines.push(`| [${f.repo}](https://github.com/${f.repo})${f.note ? `<br><sub>${cell(f.note, 60)}</sub>` : ''} | [\`${f.sha.slice(0, 7)}\`](${f.url}) | ${cell(f.date).slice(0, 10)} | ${cell(f.author, 40)} | ${cell(f.message)} | ${cell(f.paths.join(', '), 60)} |`);
        }
    } else {
        lines.push('No matching commits in this window.');
    }
    lines.push('', 'Review each commit and port what makes sense (keep `@version` bump + CHANGELOG entry). This issue is updated weekly; close it once reviewed, a new one opens on the next activity.');
    lines.push('', `<details><summary>Checked ${checked.length} repo(s)${notes.length ? `, ${notes.length} note(s)` : ''}</summary>`, '');
    for (const c of checked) lines.push(`- ${c}`);
    for (const n of notes) lines.push(`- ${cell(n, 200)}`);
    if (truncated) lines.push(`- target list truncated to ${truncated} repos (maxReposPerRun)`);
    lines.push('', '</details>');
    return lines.join('\n');
}

module.exports = async function forkWatch({ github, context, core, configPath, dryRun = false, windowDays: windowOverride, now = new Date() }) {
    const cfgFile = configPath || path.join(process.env.GITHUB_WORKSPACE || process.cwd(), '.github', 'watched-forks.json');
    const config = JSON.parse(fs.readFileSync(cfgFile, 'utf8'));
    const windowDays = Number(windowOverride) > 0 ? Number(windowOverride) : Number(config.windowDays) > 0 ? Number(config.windowDays) : 8;
    const since = new Date(now.getTime() - windowDays * DAY_MS);
    const label = config.label || 'upstream-watch';
    const title = config.issueTitle || 'Upstream / fork activity';
    const defaultPaths = Array.isArray(config.defaultPaths) && config.defaultPaths.length ? config.defaultPaths : ['vaft', 'twitch-adblock.user.js'];
    const maxRepos = Number(config.maxReposPerRun) > 0 ? Number(config.maxReposPerRun) : 60;
    const self = `${context.repo.owner}/${context.repo.repo}`;
    const notes = [];
    const checked = [];
    let rateLimited = false;

    // Every read goes through here: 404/409/archived/rate limit never abort the run.
    // After a rate limit, reads are skipped unless `always` (the issue lookup).
    async function read(what, fn, { always = false } = {}) {
        if (rateLimited && !always) return null;
        try {
            return await fn();
        } catch (err) {
            if (isRateLimit(err)) {
                rateLimited = true;
                notes.push(`rate limited during ${what}: results are partial`);
                core.warning(`fork-watch: rate limited during ${what}`);
                return null;
            }
            const s = httpStatus(err);
            const why = s === 404 ? 'not found (deleted, renamed or private)' : s === 409 ? 'empty repository' : `error ${s ?? ''} ${err?.message || err}`.replace(/\s+/g, ' ');
            notes.push(`${what}: ${why}`);
            return null;
        }
    }
    const split = (full) => {
        const [owner, repo] = String(full).split('/');
        return { owner, repo };
    };

    const rate = await read('rate limit check', () => github.rest.rateLimit.get());
    const remaining = rate?.data?.resources?.core?.remaining;
    if (typeof remaining === 'number' && remaining < 30) {
        core.warning(`fork-watch: only ${remaining} API calls left, skipping this run`);
        return { skipped: true, findings: [], newFindings: [], notes };
    }

    // 1) Targets: explicit repos first (they win de-duplication), then recent forks.
    const targets = [];
    const seenRepos = new Set([self.toLowerCase()]);
    const addTarget = (full, paths, note, meta) => {
        const key = String(full).toLowerCase();
        if (seenRepos.has(key)) return;
        seenRepos.add(key);
        targets.push({ repo: full, paths: paths && paths.length ? paths : defaultPaths, note, meta });
    };
    for (const entry of config.repos || []) {
        if (!entry || typeof entry.repo !== 'string' || !entry.repo.includes('/')) continue;
        const res = await read(`repo ${entry.repo}`, () => github.rest.repos.get(split(entry.repo)));
        if (!res) continue;
        const meta = res.data;
        const full = meta.full_name || entry.repo; // follows renames
        const note = [entry.note, meta.archived ? 'archived' : ''].filter(Boolean).join(', ');
        if (meta.pushed_at && new Date(meta.pushed_at) < since) {
            checked.push(`${full}: no push since ${String(meta.pushed_at).slice(0, 10)}${meta.archived ? ' (archived)' : ''}`);
            seenRepos.add(full.toLowerCase());
            continue;
        }
        addTarget(full, entry.paths, note, meta);
    }
    for (const entry of config.forksOf || []) {
        const parent = !entry || entry.repo === 'self' || !entry.repo ? self : entry.repo;
        const maxPages = Math.min(Math.max(Number(entry?.maxPages) || 1, 1), 10);
        let active = 0;
        let listed = 0;
        for (let page = 1; page <= maxPages; page++) {
            const res = await read(`forks of ${parent}`, () => github.rest.repos.listForks({ ...split(parent), sort: entry?.sort || 'newest', per_page: 100, page }));
            const forks = res?.data || [];
            listed += forks.length;
            for (const fork of forks) {
                if (fork.pushed_at && new Date(fork.pushed_at) >= since && !fork.disabled) {
                    active++;
                    addTarget(fork.full_name, entry?.paths, `fork of ${parent}${fork.archived ? ', archived' : ''}`, fork);
                }
            }
            if (forks.length < 100) break;
        }
        checked.push(`forks of ${parent}: ${listed} listed, ${active} pushed in the window`);
    }
    let truncated = 0;
    if (targets.length > maxRepos) {
        truncated = maxRepos;
        targets.length = maxRepos;
    }

    // 2) Commits already in this repo (e.g. a fork that only has our own commits).
    const knownShas = new Set();
    for (const p of defaultPaths) {
        const res = await read(`commits of ${self}`, () => github.rest.repos.listCommits({ ...context.repo, since: since.toISOString(), path: p, per_page: 100 }));
        for (const c of res?.data || []) knownShas.add(c.sha);
    }

    // 3) Commits in the window, per target and path.
    const bySha = new Map();
    for (const t of targets) {
        let count = 0;
        for (const p of t.paths) {
            const res = await read(`commits of ${t.repo} (${p})`, () => github.rest.repos.listCommits({ ...split(t.repo), since: since.toISOString(), path: p, per_page: 30 }));
            const commits = res?.data || [];
            if (commits.length === 30) notes.push(`${t.repo} (${p}): 30+ commits, only the latest 30 listed`);
            for (const c of commits) {
                if (!c?.sha || knownShas.has(c.sha)) continue;
                const existing = bySha.get(c.sha);
                if (existing) {
                    if (existing.repo === t.repo && !existing.paths.includes(p)) existing.paths.push(p);
                    continue;
                }
                count++;
                bySha.set(c.sha, {
                    repo: t.repo,
                    note: t.note || '',
                    sha: c.sha,
                    date: c.commit?.committer?.date || c.commit?.author?.date || '',
                    author: c.author?.login || c.commit?.author?.name || '',
                    message: c.commit?.message || '',
                    url: c.html_url || `https://github.com/${t.repo}/commit/${c.sha}`,
                    paths: [p],
                });
            }
        }
        checked.push(`${t.repo} (${t.paths.join(', ')}): ${count} commit(s)${t.note ? `, ${t.note}` : ''}`);
    }
    const findings = [...bySha.values()].sort((a, b) => String(b.date).localeCompare(String(a.date)));

    // 4) Single issue: create, or refresh body + comment only the new commits.
    const report = renderReport({ findings, checked, notes, since, now, windowDays, truncated });
    try {
        await core.summary.addRaw(report).write();
    } catch {}
    const issues = await read('open upstream-watch issue', () => github.rest.issues.listForRepo({ ...context.repo, state: 'open', labels: label, per_page: 20 }), { always: true });
    const issue = (issues?.data || []).find((i) => !i.pull_request) || null;
    const listed = new Set([...String(issue?.body || '').matchAll(/\/commit\/([0-9a-f]{40})/g)].map((m) => m[1]));
    const newFindings = findings.filter((f) => !listed.has(f.sha));
    core.info(`fork-watch: ${findings.length} commit(s) in window, ${newFindings.length} new, ${targets.length} repo(s) checked${rateLimited ? ', rate limited' : ''}`);

    if (dryRun || findings.length === 0) {
        if (dryRun) core.info(report);
        return { findings, newFindings, notes, issueNumber: issue?.number ?? null, dryRun };
    }
    // Partial results or an unknown issue state: never open a duplicate issue or overwrite the
    // open one with a partial report (its commit links de-duplicate the next runs).
    if (rateLimited || issues === null) {
        core.warning(`fork-watch: ${rateLimited ? 'rate limited' : 'could not list the open upstream-watch issue'}, issue left as is (report in the job summary)`);
        return { findings, newFindings, notes, issueNumber: issue?.number ?? null, dryRun, issueSkipped: true };
    }

    let issueNumber = issue?.number ?? null;
    try {
        try {
            await github.rest.issues.getLabel({ ...context.repo, name: label });
        } catch (err) {
            if (httpStatus(err) !== 404) throw err;
            await github.rest.issues.createLabel({ ...context.repo, name: label, color: '5319e7', description: 'Commits in upstream vaft / forks worth reviewing' });
        }
        if (!issue) {
            const created = await github.rest.issues.create({ ...context.repo, title, body: report, labels: [label] });
            issueNumber = created.data.number;
        } else {
            await github.rest.issues.update({ ...context.repo, issue_number: issue.number, body: report });
            if (newFindings.length) {
                const rows = newFindings.map((f) => `- [${f.repo}](https://github.com/${f.repo}) [\`${f.sha.slice(0, 7)}\`](${f.url}) ${cell(f.date).slice(0, 10)}: ${cell(f.message)}`);
                await github.rest.issues.createComment({ ...context.repo, issue_number: issue.number, body: `${newFindings.length} new commit(s) since the last check:\n\n${rows.join('\n')}` });
            }
        }
    } catch (err) {
        if (!isRateLimit(err)) throw err;
        notes.push('rate limited while writing the issue: not (fully) updated');
        core.warning('fork-watch: rate limited while writing the issue, it may be out of date (report in the job summary)');
        return { findings, newFindings, notes, issueNumber, dryRun, issueSkipped: true };
    }
    return { findings, newFindings, notes, issueNumber, dryRun };
};

module.exports.renderReport = renderReport;
